param([string]$Before, [string]$After, [string]$Output)
$ErrorActionPreference = 'Stop'
function Read-Ast([string]$path) {
    $tokens=$null; $errors=$null
    $ast=[Management.Automation.Language.Parser]::ParseFile($path,[ref]$tokens,[ref]$errors)
    if($errors.Count){throw 'AST parsing failed'}
    return $ast
}
function Get-Definition($ast,[string]$name) {
    $found=$ast.FindAll({param($item)
        $item -is [Management.Automation.Language.FunctionDefinitionAst] -and $item.Name -eq $name
    },$true)
    if($found.Count -ne 1){throw 'Function definition ambiguous'}
    return $found[0]
}
function Canonical($text){return $text.Replace("`r`n","`n")}
$old=Read-Ast $Before; $new=Read-Ast $After
$proof=[ordered]@{param_block_unchanged=((Canonical $old.ParamBlock.Extent.Text) -eq (Canonical $new.ParamBlock.Extent.Text))}
foreach($name in @('Write-DisconnectStep','Remove-OwnedShare','Invoke-Probe')){
    $proof[$name]=((Canonical (Get-Definition $old $name).Extent.Text) -eq (Canonical (Get-Definition $new $name).Extent.Text))
}
$a=Get-Definition $old 'Confirm-OwnedRoot'; $b=Get-Definition $new 'Confirm-OwnedRoot'
foreach($kind in @([Management.Automation.Language.IfStatementAst],[Management.Automation.Language.ForEachStatementAst])){
    $x=@($a.Body.FindAll({param($n) $n -is $kind},$true)|ForEach-Object {Canonical $_.Extent.Text})
    $y=@($b.Body.FindAll({param($n) $n -is $kind},$true)|ForEach-Object {Canonical $_.Extent.Text})
    $proof[$kind.Name]=($x.Count -eq $y.Count -and [string]::Join("`n",$x) -eq [string]::Join("`n",$y))
}
foreach($name in @('Get-Item','Get-Content','ConvertFrom-Json')){
    $x=@($a.Body.FindAll({param($n) $n -is [Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq $name},$true)|ForEach-Object {Canonical $_.Extent.Text})
    $y=@($b.Body.FindAll({param($n) $n -is [Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq $name},$true)|ForEach-Object {Canonical $_.Extent.Text})
    $proof[$name]=($x.Count -eq $y.Count -and [string]::Join("`n",$x) -eq [string]::Join("`n",$y))
}
$proof | ConvertTo-Json | Set-Content -LiteralPath $Output -Encoding UTF8
if($proof.Values -contains $false){throw 'Sensitive source flow changed'}

